  ('00000000-0000-4000-c10c-000000000010', '00000000-0000-4000-9002-00000000000c', 'Remove topsoil and spoil store', 'Topsoil reused in landscaping and surplus spoil removed.', 'in_progress', $j${"item_code":"CLO-10","category":"reinstatement","location":"East of plot 7","responsible":"Patrick Wekesa","due_date":"2026-12-11","checks":"Topsoil quantity for landscaping kept\tYes\nSurplus spoil removed\tPartly"}$j$)
) AS v(id, register_id, title, description, status, vals)
CROSS JOIN public.projects p
WHERE p.project_code = 'SEED334-PRJ-08'
ON CONFLICT (id) DO NOTHING;

-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9002-000000000001'::uuid, '00000000-0000-4000-9002-000000000002'::uuid, '00000000-0000-4000-9002-000000000003'::uuid, '00000000-0000-4000-9002-000000000004'::uuid, '00000000-0000-4000-9002-000000000005'::uuid, '00000000-0000-4000-9002-000000000006'::uuid, '00000000-0000-4000-9002-000000000007'::uuid, '00000000-0000-4000-9002-000000000008'::uuid, '00000000-0000-4000-9002-000000000009'::uuid, '00000000-0000-4000-9002-00000000000a'::uuid, '00000000-0000-4000-9002-00000000000b'::uuid, '00000000-0000-4000-9002-00000000000c'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
